111:  function updateUI(){for(const [key,val] of [['fuel',fuel],['food',food],['health',health]]){$(key+'Val').textContent=Math.max(0,Math.round(val))+'%';$(key+'Bar').style.width=Math.max(0,val)+'%';} $('distance').textContent=dist.toFixed(1).padStart(4,'0');$('progress').style.width=Math.min(100,dist)+'%';$('logTime').textContent=`DAY ${String(1+Math.floor(elapsed/55)).padStart(2,'0')}`}
