function crewState(member){return member.health<=0?'dead':member.health<=35?'critical':member.health<75?'wounded':'fit'}
  function updateCrew(){let active=0;$('crewList').innerHTML=crew.map(member=>{const state=crewState(member);if(state!=='dead')active++;const label=state==='dead'?'DOWN':state==='fit'?'FIT':state==='wounded'?'WOUNDED':'CRITICAL';return `<div class="crew-member ${state}" aria-label="${member.name}, ${label}, ${Math.round(member.health)} percent"><div class="crew-avatar">${member.initial}</div><div class="crew-info"><div class="crew-top"><span class="crew-name">${member.name}</span><span class="crew-status">${label}</span></div><div class="crew-bar"><span style="width:${Math.max(0,member.health)}%"></span></div></div></div>`}).join('');$('crewCount').textContent=`${active} / 3 ACTIVE`}
  function updateUI(){for(const [key,val] of [['fuel',fuel],['food',food],['health',health]]){$(key+'Val').textContent=Math.max(0,Math.round(val))+'%';$(key+'Bar').style.width=Math.max(0,val)+'%';} $('distance').textContent=dist.toFixed(1).padStart(4,'0');$('progress').style.width=Math.min(100,dist)+'%';$('logTime').textContent=`DAY ${String(1+Math.floor(elapsed/55)).padStart(2,'0')}`;updateCrew()}

